{
    GENERATED_BODY()
public:
    UBTTask_FindCover_16();
    virtual EBTNodeResult::Type ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory) override;

protected:
    UPROPERTY(EditAnywhere, Category="Blackboard")
    FBlackboardKeySelector CoverLocationKey;

    UPROPERTY(EditAnywhere, Category="Search")
    float SearchRadius = 1500.0f;
};

// BTTask_FindCover_16.cpp
#include "BTTask_FindCover_16.h"
#include "AIController.h"
#include "BehaviorTree/BlackboardComponent.h"
#include "NavigationSystem.h"

UBTTask_FindCover_16::UBTTask_FindCover_16()
{
    NodeName = "Find Cover Point 16";
    CoverLocationKey.AddVectorFilter(this, GET_MEMBER_NAME_CHECKED(UBTTask_FindCover_16, CoverLocationKey));
}

EBTNodeResult::Type UBTTask_FindCover_16::ExecuteTask(UBehaviorTreeComponent& OwnerComp, uint8* NodeMemory)
{
    AAIController* AICon = OwnerComp.GetAIOwner();
    UBlackboardComponent* BBComp = OwnerComp.GetBlackboardComponent();
    if (!AICon || !BBComp)
    {
        return EBTNodeResult::Failed;
    }

    APawn* AIPawn = AICon->GetPawn();
    if (!AIPawn)
    {
        return EBTNodeResult::Failed;
    }

    UNavigationSystemV1* NavSys = FNavigationSystem::GetCurrent<UNavigationSystemV1>(AIPawn->GetWorld());
    if (!NavSys)
    {
        return EBTNodeResult::Failed;
    }

    FNavLocation NavLoc;
    const FVector Origin = AIPawn->GetActorLocation();
    if (NavSys->GetRandomReachablePointInRadius(Origin, SearchRadius, NavLoc))
    {
        BBComp->SetValueAsVector(CoverLocationKey.SelectedKeyName, NavLoc.Location);
        return EBTNodeResult::Succeeded;
    }

    return EBTNodeResult::Failed;
}

