    public float3 TargetPosition;
}

[BurstCompile]
public partial struct UnitSimulationSystem_60 : ISystem
{
    [BurstCompile]
    public void OnCreate(ref SystemState state)
    {
        state.RequireForUpdate<UnitStats_60>();
    }

    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float deltaTime = SystemAPI.Time.DeltaTime;
        var job = new UpdateUnitJob_60 { DeltaTime = deltaTime };
        job.ScheduleParallel();
    }
}

[BurstCompile]
public partial struct UpdateUnitJob_60 : IJobEntity
{
    public float DeltaTime;

    private void Execute(
        ref LocalTransform transform,
        ref UnitStats_60 stats,
        in UnitMovementTarget_60 target)
    {
        // Health decay
        stats.Health -= stats.DecayRate * DeltaTime;

        // Spatial movement
        float3 toTarget = target.TargetPosition - transform.Position;
        float distSq = math.lengthsq(toTarget);
        if (distSq > 0.01f)
        {
            float3 dir = math.normalize(toTarget);
            transform.Position += dir * stats.MoveSpeed * DeltaTime;
            transform.Rotation = quaternion.LookRotationSafe(dir, math.up());
        }
    }
}

