public:
    UFUNCTION(BlueprintCallable, Category="GameForge|Collision")
    static bool PerformPenetratingCapsuleSweep(
        UObject* WorldContextObject,
        const FVector& Start,
        const FVector& End,
        float Radius,
        float HalfHeight,
        ECollisionChannel Channel,
        const TArray<AActor*>& IgnoredActors,
        TArray<FHitResult>& OutHits
    );
};

// ProjectileSweep_4.cpp
#include "ProjectileSweep_4.h"
#include "Engine/World.h"
#include "CollisionQueryParams.h"

bool UProjectileSweepLibrary_4::PerformPenetratingCapsuleSweep(
    UObject* WorldContextObject,
    const FVector& Start,
    const FVector& End,
    float Radius,
    float HalfHeight,
    ECollisionChannel Channel,
    const TArray<AActor*>& IgnoredActors,
    TArray<FHitResult>& OutHits
)
{
    if (!WorldContextObject) return false;
    UWorld* World = WorldContextObject->GetWorld();
    if (!World) return false;

    FCollisionShape CapsuleShape = FCollisionShape::MakeCapsule(Radius, HalfHeight);
    FCollisionQueryParams Params(SCENE_QUERY_STAT(PenetratingCapsuleSweep_4), false);
    Params.bReturnPhysicalMaterial = true;
    Params.AddIgnoredActors(IgnoredActors);

    return World->SweepMultiByChannel(
        OutHits,
        Start,
        End,
        FQuat::Identity,
        Channel,
        CapsuleShape,
        Params
    );
}

