// GameMath_16.h
#pragma once
#include <cmath>

struct FVec3_16
{
    float X, Y, Z;
    FVec3_16() : X(0), Y(0), Z(0) {}
    FVec3_16(float InX, float InY, float InZ) : X(InX), Y(InY), Z(InZ) {}
    static float Dot(const FVec3_16& A, const FVec3_16& B) { return A.X * B.X + A.Y * B.Y + A.Z * B.Z; }
};

struct FQuat_16
{
    float X, Y, Z, W;
    FQuat_16() : X(0), Y(0), Z(0), W(1) {}
    FQuat_16(float InX, float InY, float InZ, float InW) : X(InX), Y(InY), Z(InZ), W(InW) {}

    static FQuat_16 Slerp(const FQuat_16& Q1, const FQuat_16& Q2, float T)
    {
        float CosHalfTheta = Q1.X * Q2.X + Q1.Y * Q2.Y + Q1.Z * Q2.Z + Q1.W * Q2.W;
        FQuat_16 Target = Q2;
        if (CosHalfTheta < 0.0f)
        {
            Target = FQuat_16(-Q2.X, -Q2.Y, -Q2.Z, -Q2.W);
            CosHalfTheta = -CosHalfTheta;
        }

        if (std::abs(CosHalfTheta) >= 1.0f) return Q1;

        float HalfTheta = std::acos(CosHalfTheta);
        float SinHalfTheta = std::sqrt(1.0f - CosHalfTheta * CosHalfTheta);

        if (std::abs(SinHalfTheta) < 0.001f)
        {
            return FQuat_16(
                Q1.X * 0.5f + Target.X * 0.5f,
                Q1.Y * 0.5f + Target.Y * 0.5f,
                Q1.Z * 0.5f + Target.Z * 0.5f,
                Q1.W * 0.5f + Target.W * 0.5f
            );
        }

        float RatioA = std::sin((1.0f - T) * HalfTheta) / SinHalfTheta;
        float RatioB = std::sin(T * HalfTheta) / SinHalfTheta;

        return FQuat_16(
            Q1.X * RatioA + Target.X * RatioB,
            Q1.Y * RatioA + Target.Y * RatioB,
            Q1.Z * RatioA + Target.Z * RatioB,
            Q1.W * RatioA + Target.W * RatioB
        );
    }
};

