use bevy::prelude::*;

#[derive(Component)]
pub struct Projectile_34 {
    pub velocity: Vec3,
    pub lifetime: Timer,
}

#[derive(Resource)]
pub struct CombatConfig_34 {
    pub base_speed: f32,
    pub max_lifetime: f32,
}

pub struct CombatPlugin_34;

impl Plugin for CombatPlugin_34 {
    fn build(&self, app: &mut App) {
        app.insert_resource(CombatConfig_34 {
            base_speed: 45.0,
            max_lifetime: 3.5,
        })
        .add_systems(Update, (update_projectiles_34, cleanup_expired_projectiles_34));
    }
}

fn update_projectiles_34(
    time: Res<Time>,
    mut query: Query<(&mut Transform, &mut Projectile_34)>,
) {
    for (mut transform, mut proj) in query.iter_mut() {
        proj.lifetime.tick(time.delta());
        transform.translation += proj.velocity * time.delta_seconds();
    }
}

fn cleanup_expired_projectiles_34(
    mut commands: Commands,
    query: Query<(Entity, &Projectile_34)>,
) {
    for (entity, proj) in query.iter() {
        if proj.lifetime.finished() {
            commands.entity(entity).despawn_recursive();
        }
    }
}

